def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = unparsed_arguments[:]

    # Try each subparser to parse the arguments
    for subparser_name, subparser in subparsers.items():
        try:
            # Parse known args and allow for unknown ones
            ns, remaining = subparser.parse_known_args(remaining_arguments)
            parsed_arguments[subparser_name] = ns
            remaining_arguments = remaining
        except SystemExit:
            # If parsing fails, skip this subparser
            continue

    return parsed_arguments, remaining_arguments

