def deep_merge_nodes(nodes):
    from collections.abc import Mapping

    def merge(a, b):
        if not isinstance(a, Mapping) or not isinstance(b, Mapping):
            return b
        for key in b:
            if key in a:
                a[key] = merge(a[key], b[key])
            else:
                a[key] = b[key]
        return a

    result = {}
    for node in nodes:
        result = merge(result, node)
    return result

import argparse
def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = unparsed_arguments[:]

    for subparser_name, subparser in subparsers.items():
        try:
            # Attempt to parse the arguments with the current subparser
            parsed_namespace = subparser.parse_args(remaining_arguments)
            parsed_arguments[subparser_name] = parsed_namespace

            # Update remaining arguments to exclude those that were successfully parsed
            remaining_arguments = unparsed_arguments[len(vars(parsed_namespace)):]
        except SystemExit:
            # If parsing fails, continue to the next subparser
            continue

    return parsed_arguments, remaining_arguments

def parse_arguments(*unparsed_arguments):
    if len(unparsed_arguments) % 2!= 0:
        raise ValueError("Arguments must be provided in key-value pairs.")

    parsed_arguments = {}
    it = iter(unparsed_arguments)

    for key in it:
        try:
            value = next(it)
            if key.startswith('--'):
                parsed_arguments[key[2:]] = value
            else:
                raise ValueError(f"Argument '{key}' is not in the expected format.")
        except StopIteration:
            raise ValueError("Incomplete key-value pair.")

    return parsed_arguments

