def deep_merge_nodes(nodes):
    def merge(a, b):
        if isinstance(a, Mapping) and isinstance(b, Mapping):
            result = dict(a)
            for k, v in b.items():
                if k in result:
                    result[k] = merge(result[k], v)
                else:
                    result[k] = v
            return result
        return b

    if not nodes:
        return {}

    result = nodes[0]
    for node in nodes[1:]:
        result = merge(result, node)

    return result

