def validate_fixity(self, fixity, manifest_files):
    if not isinstance(fixity, dict):
        self.error("Fixity block must be a dictionary.")
        return

    for file_path, checksum_info in fixity.items():
        if not isinstance(checksum_info, dict):
            self.error(f"Fixity information for {file_path} must be a dictionary.")
            return

        if 'type' not in checksum_info or 'value' not in checksum_info:
            self.error(f"Fixity information for {file_path} must contain 'type' and 'value'.")
            return

        if file_path not in manifest_files:
            self.error(f"File {file_path} in fixity block is not listed in the manifest.")
            return

        if checksum_info['type'] not in ['sha256','md5','sha1']:
            self.error(f"Unsupported checksum type {checksum_info['type']} for file {file_path}.")
            return

