def find_path_type(path):
    if os.path.exists(path):
        if os.path.isfile(path):
            return "File"
        elif os.path.isdir(path):
            return "Directory"
        elif os.path.islink(path):
            return "Symbolic Link"
        else:
            return "Other"
    else:
        return "Does not exist"

