def validate_version_inventories(self, version_dirs, root_inventory_path):
    root_digests = {}
    discrepancies = []

    # Load root inventory digests
    with open(root_inventory_path, 'r') as root_file:
        for line in root_file:
            parts = line.strip().split()
            if len(parts) == 2:
                root_digests[parts[0]] = parts[1]

    # Validate each version directory
    for version in version_dirs:
        inventory_path = os.path.join(version, 'inventory.txt')
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory file missing for version {version}")

        current_digests = {}
        with open(inventory_path, 'r') as inventory_file:
            for line in inventory_file:
                parts = line.strip().split()
                if len(parts) == 2:
                    current_digests[parts[0]] = parts[1]

        # Compare with root digests
        for item, digest in current_digests.items():
            if item in root_digests and root_digests[item]!= digest:
                discrepancies.append((item, root_digests[item], digest, version))

    if discrepancies:
        print("Discrepancies found in content digests:")
        for item, root_digest, current_digest, version in discrepancies:
            print(f"Item: {item}, Root Digest: {root_digest}, Current Digest: {current_digest}, Version: {version}")

    print("Validation complete.")

