def _explore_folder(folder):
    def _group_files_by_xml_filename(files):
        grouped_files = defaultdict(list)
        for file in files:
            if file.endswith('.xml'):
                base_name = os.path.splitext(file)[0]
                grouped_files[base_name].append(file)
        return grouped_files

    all_files = os.listdir(folder)
    grouped_files = _group_files_by_xml_filename(all_files)

    return grouped_files

import os
def _eval_file(prefix, file_path):
    if not file_path.startswith(prefix):
        return None

    _, file_extension = os.path.splitext(file_path)
    file_extension = file_extension.lower()

    if file_extension == '.xml':
        return None

    component_id = os.path.basename(file_path).split('.')[0]

    if file_extension == '.pdf':
        return {'component_id': component_id, 'file_path': file_path}
    else:
        return {'component_id': component_id, 'file_path': file_path, 'ftype': file_extension}

