def absorb(self, args):
    def absorb_expr(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == 'and':
                if left == right:
                    return left
                if isinstance(left, tuple) and left[0] == 'or' and left[1] == left:
                    return right
                if isinstance(right, tuple) and right[0] == 'or' and right[1] == right:
                    return left
            if op == 'or':
                if left == right:
                    return left
                if isinstance(left, tuple) and left[0] == 'and' and left[1] == left:
                    return right
                if isinstance(right, tuple) and right[0] == 'and' and right[1] == right:
                    return left
        return expr

    result = []
    for expr in args:
        simplified_expr = absorb_expr(expr)
        result.append(simplified_expr)
    return result

class HookManager:
    def __init__(self):
        self.registry = {}

    def on(self, hook):
        def decorator(func):
            if hook not in self.registry:
                self.registry[hook] = []
            self.registry[hook].append(func)
            return func
        return decorator

