def generate_default_observer_schema(app):
    default_schema = {
       'version': 'v1',
       'resources': {}
    }

    custom_schemas = app.get('custom_observer_schemas', {})

    for resource in app['spec']['manifest']:
        resource_name = resource['metadata']['name']

        if resource_name not in custom_schemas:
            default_resource_schema = {
               'version': 'v1',
                'kind': resource['kind'],
               'metadata': resource['metadata'],
               'spec': resource.get('spec', {})
            }

            default_schema['resources'][resource_name] = default_resource_schema

    app['observer_schemas'] = custom_schemas
    app['observer_schemas'].update(default_schema['resources'])

    return app

