    def update_dict_from_schema(last_applied_dict, schema_dict, response_dict):
        for key in schema_dict:
            if key not in last_applied_dict:
                last_applied_dict[key] = response_dict.get(key)
            elif isinstance(last_applied_dict[key], dict) and isinstance(response_dict.get(key), dict):
                update_dict_from_schema(last_applied_dict[key], schema_dict[key], response_dict[key])

    for i, schema_item in enumerate(observer_schema):
        response_item = response[i] if i < len(response) else {}
        last_applied_item = last_applied_manifest[i] if i < len(last_applied_manifest) else {}
