def difference(d1, d2, level=-1):
    def _compare(d1, d2, level):
        if level == 0:
            return {}
        diff = {}
        for k, v in d1.items():
            if k not in d2:
                diff[k] = v
            elif isinstance(v, dict) and isinstance(d2[k], dict):
                nested_diff = _compare(v, d2[k], level - 1)
                if nested_diff:
                    diff[k] = nested_diff
            elif v!= d2[k]:
                diff[k] = v
        return diff

    return _compare(d1, d2, level)

