def integral(bins, edges):
    area = 0.0
    for i in range(len(bins)):
        width = edges[i+1] - edges[i]
        if i == len(bins) - 1:
            area += 0.5 * bins[i] * width
        else:
            area += 0.5 * (bins[i] + bins[i+1]) * width
    return area

