class Histogram:
    def __init__(self):
        self._data = []
        self._scale = None

    def fill(self, value):
        self._data.append(value)
        self._scale = None  # Invalidate scale when histogram is changed

    def compute_scale(self):
        if not self._data:
            return 0
        # Example scale computation as integral of values
        return sum(self._data)

    def scale(self, other=None, recompute=False):
        if other is None:
            if self._scale is None or recompute:
                self._scale = self.compute_scale()
            return self._scale

        if not isinstance(other, (int, float)):
            raise LenaValueError("Provided 'other' must be a float or int.")

        if self._scale is None or self._scale == 0:
            raise LenaValueError("Histogram scale is zero, cannot rescale.")

        rescale_factor = other / self._scale
        if rescale_factor == 0:
            raise LenaValueError("Rescale factor is zero, cannot rescale.")

        self._data = [x * rescale_factor for x in self._data]
        self._scale = other  # New scale is set to 'other'
