class Graph:
    def __init__(self, coordinates, scale=None):
        self.coordinates = coordinates
        self.scale = scale

    def scale(self, other=None):
        if other is None:
            return self.scale

        if self.scale is None or self.scale == 0:
            raise LenaValueError("Graph has unknown or zero scale.")

        num_dimensions = len(self.coordinates[0]) if self.coordinates else 0
        if num_dimensions == 0:
            raise LenaValueError("Graph has no coordinates.")

        for coord in self.coordinates:
            if len(coord)!= num_dimensions:
                raise LenaValueError("Inconsistent coordinate dimensions.")

        scale_factor = other / self.scale
        for coord in self.coordinates:
            coord[-1] *= scale_factor

        self.scale = other

