class Graph:
    def __init__(self, fields, error_indices):
        self.fields = fields
        self.error_indices = error_indices

    def _update_context(self, context):
        # Define default error names based on the first three coordinates
        error_names = ["x", "y", "z"]

        # Initialize the error subcontext if not present
        if "error" not in context:
            context["error"] = {}

        # Iterate over the error names and update the context
        for i, error_name in enumerate(error_names):
            if i < len(self.fields):
                # Create a subcontext for each error name
                subcontext = context["error"].setdefault(error_name, {})
                index = self.error_indices.get(self.fields[i], None)
                if index is not None:
                    # Append error index to the subcontext
                    if "index" not in subcontext:
                        subcontext["index"] = []
                    subcontext["index"].append(index)

