def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    # Default make_value function if not provided
    if make_value is None:
        make_value = lambda bin_: bin_

    # Determine scale if not provided
    if scale is None:
        scale = hist.scale if hasattr(hist,'scale') and hist.scale else None

    # Prepare the graph data structure
    GraphPoint = namedtuple('GraphPoint', field_names)
    graph_points = []

    # Iterate over histogram bins
    for i, bin_ in enumerate(hist.bins):
        # Get the value for the graph point
        value = make_value(bin_)

        # Determine the x-coordinate based on get_coordinate
        if get_coordinate == "left":
            x = hist.bin_edges[i]
        elif get_coordinate == "right":
            x = hist.bin_edges[i + 1] if i + 1 < len(hist.bin_edges) else hist.bin_edges[i]
        elif get_coordinate == "middle":
            x = (hist.bin_edges[i] + hist.bin_edges[i + 1]) / 2 if i + 1 < len(hist.bin_edges) else hist.bin_edges[i]
        else:
            raise ValueError("Invalid get_coordinate value. Choose from 'left', 'right','middle'.")

        # Create a graph point with the determined x and value
        if len(field_names) == 2:
            graph_points.append(GraphPoint(x, value))
        else:
            graph_points.append(GraphPoint(x, *value))

    # Create the graph with the determined scale
    graph = {
        'points': graph_points,
       'scale': scale
    }

    return graph

