def render(pieces, style):
    rendered_pieces = []

    for piece in pieces:
        if style == "uppercase":
            rendered_piece = piece.upper()
        elif style == "lowercase":
            rendered_piece = piece.lower()
        elif style == "titlecase":
            rendered_piece = piece.title()
        else:
            rendered_piece = piece  # Default to no change if style is unrecognized

        rendered_pieces.append(rendered_piece)

    return rendered_pieces

