def _normalizeargs(sequence, output=None):
    if output is None:
        output = []

    def expand(item):
        if isinstance(item, (list, tuple)):
            for sub_item in item:
                expand(sub_item)
        elif hasattr(item, '__iter__') and not isinstance(item, str):
            for sub_item in item:
                expand(sub_item)
        else:
            output.append(item)

    for item in sequence:
        expand(item)

    return output

def names(self, all=False):
    if all:
        return list(self.__dict__.keys())
    else:
        return [attr for attr in dir(self) if not attr.startswith('__') and not callable(getattr(self, attr))]

def namesAndDescriptions(self, all=False):
    attributes = {}
    for attr_name in dir(self):
        if not attr_name.startswith('__') or all:
            attr = getattr(self, attr_name)
            if callable(attr) or not isinstance(attr, property):
                description = attr.__doc__.split('\n')[0] if attr.__doc__ else "No description"
                attributes[attr_name] = description
    return attributes

