from inspect import signature, Parameter
def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    # Check if the candidate claims to provide the interface
    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"{candidate} does not provide {iface}")

    # Check methods
    iface_methods = iface.names()
    candidate_methods = dir(candidate)

    for method in iface_methods:
        if method not in candidate_methods:
            errors.append(f"Missing method: {method}")
            continue

        iface_method = getattr(iface, method)
        candidate_method = getattr(candidate, method)

        iface_sig = signature(iface_method)
        candidate_sig = signature(candidate_method)

        if iface_sig!= candidate_sig:
            errors.append(f"Method {method} signature mismatch: "
                          f"expected {iface_sig}, got {candidate_sig}")

    # Check attributes
    iface_attrs = iface.names()
    candidate_attrs = dir(candidate)

    for attr in iface_attrs:
        if attr not in candidate_attrs:
            errors.append(f"Missing attribute: {attr}")

    # Raise errors if any
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

