def verifyObject(iface, candidate, tentative=False):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"{candidate} does not provide the interface {iface}")

    for name, spec in iface.namesAndDescriptions(abstract=1):
        if not hasattr(candidate, name):
            errors.append(f"{candidate} does not have the method/attribute '{name}' required by {iface}")
        else:
            method = getattr(candidate, name)
            try:
                verifyObject(spec, method)
            except Invalid as e:
                errors.append(str(e))

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    iface_methods = set(dir(iface))
    candidate_methods = set(dir(candidate))

    # Exclude magic methods and properties starting with underscores
    iface_methods = {m for m in iface_methods if not m.startswith('__') or m in ['__init__', '__call__']}
    candidate_methods = {m for m in candidate_methods if not m.startswith('__')}

    # Check for required methods
    missing_methods = iface_methods - candidate_methods
    if missing_methods:
        return False

    # Check for method signatures if not tentative
    if not tentative:
        for method in iface_methods:
            iface_method = getattr(iface, method, None)
            candidate_method = getattr(candidate, method, None)
            if callable(iface_method) and callable(candidate_method):
                iface_signature = iface_method.__code__.co_varnames
                candidate_signature = candidate_method.__code__.co_varnames
                if iface_signature!= candidate_signature:
                    return False

    return True

def determineMetaclass(bases, explicit_mc=None):
    if explicit_mc is not None:
        return explicit_mc

    # Gather all metaclasses from the base classes
    metaclasses = {type(base) for base in bases}

    # Handle the case where there are no base classes
    if not metaclasses:
        return type

    # If only one metaclass, return it
    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If there are multiple metaclasses, find a common metaclass
    # Start with the first metaclass
    metaclass = list(metaclasses)[0]

    for candidate in metaclasses:
        # Check if the candidate metaclass is a subclass of the current metaclass
        if not issubclass(candidate, metaclass):
            # Try creating a new metaclass that is a subclass of both
            metaclass = type('Meta', (metaclass, candidate), {})
            break

    return metaclass

def minimalBases(classes):
    subclass_map = {}

    for cls in classes:
        for subclass in cls.__subclasses__():
            subclass_map.setdefault(subclass, []).append(cls)
            subclass_map.setdefault(cls, [])

    return [cls for cls, parents in subclass_map.items() if not parents]

