def extostr(cls, e, max_level=30, max_path_level=5):
    def format_traceback(tb, level=0):
        if level > max_level:
            return '... (truncated)\n'
        s = ''
        if tb.tb_next:
            s += format_traceback(tb.tb_next, level + 1)
        s +=' File "{}", line {}, in {}\n'.format(
            tb.tb_frame.f_code.co_filename, tb.tb_lineno, tb.tb_frame.f_code.co_name
        )
        if level < max_path_level:
            s +='   {}\n'.format(''.join(tb.tb_frame.f_code.co_firstlineno))
        return s

    output = f'{cls.__name__}: {str(e)}\n'

    tb = e.__traceback__
    while tb is not None:
        output += format_traceback(tb)
        tb = tb.tb_next

    return output

