from collections import defaultdict, OrderedDict
from functools import wraps
class LFUCache:
    def __init__(self, maxsize=128, typed=False):
        self.maxsize = maxsize
        self.typed = typed
        self.cache = {}
        self.freq = defaultdict(OrderedDict)
        self.min_freq = 0

    def get_key(self, args, kwargs):
        key = args
        if self.typed:
            key += tuple(sorted((k, type(v)) for k, v in kwargs.items()))
        else:
            key += tuple(sorted(kwargs.items()))
        return key

    def __call__(self, func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            key = self.get_key(args, kwargs)

            # Check if key is in cache
            if key in self.cache:
                # Update frequency
                self.freq[key[1]][key] += 1
                self.cache[key] = (self.freq[key[1]][key], self.cache[key][1])
                return self.cache[key][1]

            # Compute result and store it
            result = func(*args, **kwargs)
            self.cache[key] = (1, result)
            self.freq[1][key] = 1
            self.min_freq = 1

            if len(self.cache) > self.maxsize:
                # Evict least frequently used item
                oldest = next(iter(self.freq[self.min_freq]))
                del self.freq[self.min_freq][oldest]
                if not self.freq[self.min_freq]:
                    del self.freq[self.min_freq]
                del self.cache[oldest]

            return result

        return wrapped
def lfu_cache(maxsize=128, typed=False):
    return LFUCache(maxsize, typed)

class LFUCache:
    def __init__(self):
        self.key_freq = {}
        self.freq_keys = {}
        self.min_freq = 0

    def popitem(self):
        if not self.freq_keys:
            return None

        # Access the keys with the minimum frequency
        keys_with_min_freq = self.freq_keys[self.min_freq]
        key_to_remove = keys_with_min_freq.pop(0)

        # If no keys are left with the current minimum frequency, update min_freq
        if not keys_with_min_freq:
            del self.freq_keys[self.min_freq]
            self.min_freq += 1

        # Remove the key from the key_freq dictionary
        value = self.key_freq.pop(key_to_remove)

        return key_to_remove, value

    def access(self, key):
        if key in self.key_freq:
            # Update frequency
            freq = self.key_freq[key][1]
            self.key_freq[key] = (self.key_freq[key][0], freq + 1)
            self.freq_keys[freq].remove(key)
            if not self.freq_keys[freq]:
                del self.freq_keys[freq]
            self.freq_keys.setdefault(freq + 1, []).append(key)
            # Update min_freq if necessary
            if freq == self.min_freq and not self.freq_keys[freq]:
                self.min_freq += 1
        else:
            # Handle case where key is not present
            pass

    def insert(self, key, value):
        self.key_freq[key] = (value, 1)
        self.freq_keys.setdefault(1, []).append(key)
        self.min_freq = 1

from collections import OrderedDict
class LRUCache:
    def __init__(self, maxsize=128, typed=False):
        self.maxsize = maxsize
        self.typed = typed
        self.cache = OrderedDict()

    def __call__(self, func):
        def wrapped_func(*args, **kwargs):
            key = self._make_key(args, kwargs)
            if key in self.cache:
                self.cache.move_to_end(key)
                return self.cache[key]
            result = func(*args, **kwargs)
            self.cache[key] = result
            if len(self.cache) > self.maxsize:
                self.cache.popitem(last=False)
            return result

        return wrapped_func

    def _make_key(self, args, kwargs):
        key = args
        if self.typed:
            key += tuple(sorted(kwargs.items()))
            key += tuple(type(arg) for arg in args)
            key += tuple(type(value) for value, _ in sorted(kwargs.items()))
        else:
            key += tuple(sorted(kwargs.items()))
        return key
def lru_cache(maxsize=128, typed=False):
    return LRUCache(maxsize, typed)

from functools import wraps
from collections import OrderedDict
def mru_cache(maxsize=128, typed=False):
    def decorating_function(user_function):
        cache = OrderedDict()
        cache_get = cache.get
        cache_move_to_end = cache.move_to_end

        @wraps(user_function)
        def wrapper(*args, **kwargs):
            key = args if not typed else args + tuple(sorted(kwargs.items()))
            try:
                result = cache_get(key, None)
                if result is not None:
                    cache_move_to_end(key)
                    return result
            except TypeError:
                pass

            result = user_function(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)
            cache_move_to_end(key)
            return result

        def cache_clear():
            cache.clear()

        wrapper.cache_clear = cache_clear
        return wrapper

    return decorating_function

class CustomDict:
    def __init__(self):
        self._data = []
        self._key_map = {}

    def __setitem__(self, key, value):
        if key in self._key_map:
            self._data[self._key_map[key]] = (key, value)
        else:
            self._data.append((key, value))
            self._key_map[key] = len(self._data) - 1

    def __getitem__(self, key):
        return self._data[self._key_map[key]][1]

    def __delitem__(self, key):
        index = self._key_map.pop(key)
        self._data.pop(index)
        for k, i in self._key_map.items():
            if i > index:
                self._key_map[k] = i - 1

    def popitem(self):
        if not self._data:
            raise KeyError("popitem(): dictionary is empty")
        key, value = self._data.pop()
        del self._key_map[key]
        return key, value

    def __len__(self):
        return len(self._data)

    def __contains__(self, key):
        return key in self._key_map

    def items(self):
        return self._data.copy()

    def keys(self):
        return [key for key, _ in self._data]

    def values(self):
        return [value for _, value in self._data]

