def cached(cache, key=hash, lock=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = key((func, args, frozenset(kwargs.items())))
            if lock:
                with lock:
                    result = cache.get(cache_key)
                    if result is None:
                        result = func(*args, **kwargs)
                        cache[cache_key] = result
                    return result
            else:
                result = cache.get(cache_key)
