import shutil
def normalize_cmd(cmd: tuple[str,...]) -> tuple[str,...]:
    normalized_cmd = []
    for part in cmd:
        if os.path.basename(part) in os.environ['PATH'].split(os.pathsep):
            # Check if the command is an executable in the PATH
            full_path = shutil.which(part)
            if full_path:
                normalized_cmd.append(full_path)
            else:
                normalized_cmd.append(part)
        else:
            normalized_cmd.append(part)
    return tuple(normalized_cmd)

import subprocess
import os
from typing import Sequence, Tuple
from multiprocessing import Pool
def _get_platform_max_length() -> int:
    return os.sysconf('SC_ARG_MAX') if os.name!= 'nt' else 32768
def _run_command(args: Tuple[str,...], **kwargs):
    result = subprocess.run(args, **kwargs)
    return result.returncode
def _format_output(returncode: int, color: bool) -> str:
    if color:
        return f"\033[92mSuccess\033[0m" if returncode == 0 else f"\033[91mFailure\033[0m"
    return "Success" if returncode == 0 else "Failure"
def xargs(cmd: Tuple[str,...], varargs: Sequence[str], *, color: bool = False, target_concurrency: int = 1, _max_length: int = _get_platform_max_length(), **kwargs):
    def chunk_sequence(seq, size):
        for i in range(0, len(seq), size):
            yield seq[i:i + size]

    max_cmd_length = _max_length - sum(len(arg) + 2 for arg in cmd)
    chunk_size = max(1, max_cmd_length // max(len(arg) for arg in varargs))

    with Pool(processes=target_concurrency) as pool:
        results = []
        for chunk in chunk_sequence(varargs, chunk_size):
            full_cmd = (*cmd, *chunk)
            result = pool.apply_async(_run_command, (full_cmd,), kwargs)
            results.append(result)

        for result in results:
            returncode = result.get()
            print(_format_output(returncode, color))

