def point_type(name, fields, srid_map):
    def init(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        for field, value in zip(fields, args):
            setattr(self, field, value)
        for field, value in kwargs.items():
            setattr(self, field, value)

    def __setattr__(self, key, value):
        if key in fields:
            super().__setattr__(key, value)
        else:
            raise AttributeError(f"'{name}' object has no attribute '{key}'")

    def __repr__(self):
        field_values = ', '.join(f"{field}={repr(getattr(self, field))}" for field in fields)
        return f"{name}({field_values})"

    def srid(self):
        return srid_map.get(self.__class__.__name__, None)

    def __init_subclass__(cls, **kwargs):
        cls._srid = srid_map.get(cls.__name__, None)

    attrs = {
        '__init__': init,
        '__setattr__': __setattr__,
        '__repr__': __repr__,
       'srid': srid,
        '__init_subclass__': __init_subclass__,
    }

    return type(name, (ShapelyPoint,), attrs)

def round_half_to_even(n):
    import math
    if n >= 0:
        return math.floor(n + 0.5)
    else:
        return math.ceil(n - 0.5)

    # Extract the fractional part
    frac_part = n - int(n)

    # Check if the number is exactly halfway between two integers
    if frac_part == 0.5:
        # If the integer part is even, round down; if odd, round up
        return int(n) if int(n) % 2 == 0 else int(n) + 1
    elif frac_part == -0.5:
        # If the integer part is even, round up; if odd, round down
        return int(n) if int(n) % 2 == 0 else int(n) - 1
    else:
        # Use standard rounding for all other cases
        return int(n + 0.5) if n > 0 else int(n - 0.5)

