class Time:
    @classmethod
    def from_ticks(cls, ticks, tz=None):
        if not isinstance(ticks, int):
            raise ValueError("Ticks must be an integer.")
        if not (0 <= ticks < 86400000000000):
            raise ValueError("Ticks is out of bounds (0 <= ticks < 86400000000000).")

        # Convert nanoseconds to seconds and the remainder nanoseconds
        seconds, nanos = divmod(ticks, 1_000_000_000)
        td = timedelta(seconds=seconds, microseconds=nanos // 1000)

        # Create a time object from the timedelta
        time_obj = (time(0) + td).time()

        return cls(time_obj, tz)

    def __init__(self, time_obj, tz=None):
        self.time_obj = time_obj
        self.tz = tz

    def __repr__(self):
        tz_info = f" {self.tz}" if self.tz else ""
        return f"Time({self.time_obj}{tz_info})"

