from typing import Optional, Union
def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    tmp_path = Path(tmp_path)
    archive_path = Path(archive_path)

    if not archive_path.exists():
        raise FileNotFoundError(f"The archive {archive_path} does not exist.")

    if not tmp_path.exists():
        raise FileNotFoundError(f"The temporary path {tmp_path} does not exist.")

    extracted_dir = None
    try:
        if archive_path.suffix in ['.tar', '.tar.gz', '.tgz']:
            with tarfile.open(archive_path, 'r:*') as archive:
                extracted_dir = archive.extractall(path=tmp_path)
        elif archive_path.suffix == '.zip':
            with zipfile.ZipFile(archive_path, 'r') as archive:
                extracted_dir = archive.extractall(path=tmp_path)
        else:
            raise ValueError(f"Unsupported archive format: {archive_path.suffix}")

        if filename:
            extracted_dir = tmp_path / filename
            if not extracted_dir.exists():
                raise FileNotFoundError(f"Extracted directory or file {extracted_dir} does not exist.")
        else:
            extracted_dir = next(iter(tmp_path.iterdir()), None)
            if not extracted_dir:
                raise FileNotFoundError("No directory found after extraction.")

        repo_url = f"file://{extracted_dir.resolve()}"
        return repo_url
    finally:
        if extracted_dir and extracted_dir!= tmp_path:
            for item in extracted_dir.iterdir():
                if item.is_dir():
                    shutil.rmtree(item)
                else:
                    item.unlink()

from datetime import timedelta
def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        number, unit = frequency.split()
        number = int(number)
    except ValueError:
        raise ValueError("Invalid frequency format")

    unit_conversion = {
        "second": "seconds",
        "minute": "minutes",
        "hour": "hours",
        "day": "days",
        "week": "weeks",
        "month": "days",  # Approximation, 1 month = 30 days
        "year": "days"    # Approximation, 1 year = 365 days
    }

    unit = unit_conversion.get(unit.lower())
    if unit is None:
        raise ValueError("Invalid time unit")

    if unit == "days":
        if frequency.endswith("month"):
            number *= 30
        elif frequency.endswith("year"):
            number *= 365

    return timedelta(**{unit: number})

def is_local(host):
    import socket

    # List of known localhost identifiers
    localhost_identifiers = [
        "localhost",
        "127.0.0.1"
    ]

    # Attempt to resolve the host to an IP address
    try:
        ip = socket.gethostbyname(host)
        # Check if the resolved IP is 127.0.0.1
        if ip == "127.0.0.1":
            return True
    except socket.error:
        pass

    # Check if the host is in the known localhost identifiers
    if host in localhost_identifiers:
        return True

    # Check if the host is the local machine's hostname
    try:
        local_hostname = socket.gethostname()
        local_ip = socket.gethostbyname(local_hostname)
        if host == local_hostname or ip == local_ip:
            return True
    except socket.error:
        pass

    return False

