    return True

from typing import Optional, Set
from rdflib import Graph, URIRef, Node
def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = set()

    all_nodes = set(graph.all_nodes())
    child_nodes = set(graph.subjects(None, None))

    for child in child_nodes:
        if not any(graph.value(child, prop, None)):
            roots.add(child)

    non_root_nodes = set(graph.subjects(None, None))
    for node in non_root_nodes:
        if any(graph.value(node, prop, None)):
            all_nodes.discard(node)

    return all_nodes - non_root_nodes

