def load_configurations(config_filenames: Sequence[str], overrides: Optional[Dict] = None, resolve_env: bool = True) -> Tuple[Dict[str, dict], Sequence[logging.LogRecord]]:
    parsed_configs = {}
    error_log_records = []
    logger = logging.getLogger(__name__)

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config_data = file.read()
                if resolve_env:
                    config_data = os.path.expandvars(config_data)
                config = json.loads(config_data)

                if overrides:
                    config.update(overrides)

                parsed_configs[filename] = config

        except (PermissionError, json.JSONDecodeError) as e:
            log_record = logger.error(f"Error reading or parsing {filename}: {e}")
            error_log_records.append(log_record)
        except Exception as e:
            log_record = logger.error(f"Unexpected error with {filename}: {e}")
            error_log_records.append(log_record)

    return parsed_configs, error_log_records

