import re
def _include_groups(self, parser_dict):
    include_pattern = re.compile(r'^\s*#include\s+"(.+?)"\s*$')

    def resolve_includes(content, base_path):
        lines = content.splitlines()
        resolved_content = []
        for line in lines:
            match = include_pattern.match(line)
            if match:
                include_file = match.group(1)
                if include_file in parser_dict:
                    included_content = resolve_includes(parser_dict[include_file], base_path)
                    resolved_content.append(included_content)
                else:
                    raise FileNotFoundError(f"Include file '{include_file}' not found.")
            else:
                resolved_content.append(line)
        return "\n".join(resolved_content)

    resolved_dict = {}
    for file_name, content in parser_dict.items():
        resolved_dict[file_name] = resolve_includes(content, file_name)

    return resolved_dict

