    for arg_name, (value, max_length) in args.items():
        if len(value) > max_length:
            raise ValueError(f"Argument '{arg_name}' exceeds maximum length of {max_length}.")

def validate_choices_args(self, args):
    errors = {}
    for arg, value in args.items():
        if arg in self.choices:
            valid_choices = self.choices[arg]
            if not isinstance(value, list):
                value = [value]
            invalid_values = [v for v in value if v not in valid_choices]
            if invalid_values:
                errors[arg] = invalid_values
        else:
            errors[arg] = ["No valid choices defined for this argument"]
    if errors:
        raise ValueError(f"Invalid argument values found: {errors}")

def validate_min_max_args(self, args):
    for arg in args:
        if not isinstance(arg, (int, float)):
            raise ValueError(f"Argument {arg} is not a number.")
        if arg < self.min_value or arg > self.max_value:
            return False
    return True

