import subprocess
import os
def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    # Construct the base command
    command = ["ansible-playbook", playbook_path]

    # Add verbosity option if specified
    if verbose is not None:
        command.extend(['-v'] * verbose)

    # Convert extra_vars dict to JSON string and append to command if provided
    if extra_vars:
        import json
        extra_vars_string = json.dumps(extra_vars)
        command.extend(['-e', extra_vars_string])

    # Append additional ansible arguments if provided
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, list):
                command.extend([f'--{key}'] + value)
            else:
                command.extend([f'--{key}', str(value)])

    # Ensure playbook path is valid
    if not os.path.exists(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Execute the command
    process = subprocess.run(command, capture_output=True, text=True)

    # Handle the output and errors
    if process.returncode!= 0:
        raise RuntimeError(f"An error occurred while running ansible-playbook: {process.stderr}")

    return process.stdout

