import requests
def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    if not isinstance(url, str):
        raise ValueError("URL must be a string.")
    if not isinstance(data, (dict, list)):
        raise ValueError("Data must be a dictionary or list.")
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        raise ValueError("Timeout must be a positive number.")
    if method.lower() not in ["post", "get", "put", "delete"]:
        raise ValueError("Method must be one of 'post', 'get', 'put', 'delete'.")

    try:
        if method.lower() == "post":
            response = requests.post(url, json=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "get":
            response = requests.get(url, params=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "put":
            response = requests.put(url, json=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "delete":
            response = requests.delete(url, json=data, timeout=timeout, *args, **kwargs)

        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        raise RuntimeError(f"An error occurred while sending the document: {e}")
